#!/usr/bin/env bash
# verify_android_foreign_host.sh [--version X.Y.Z] [--evidence PATH] [--head-sha SHA]
#
# Advisory foreign-host proof (AND-03): a fresh Gradle project generated by the PUBLISHED
# Hex generator resolves the PUBLISHED Maven Central coordinate of the Android shell core and
# passes a host-owned JVM test, in a clean HOME and GRADLE_USER_HOME with no credentials.
# The proof is of the published generator's output and the published AAR, not of this checkout:
# the checkout is read only for the single `coordinates(` call that names the group and artifact.
#
# Seven legs run in order; the first failing leg stops the run (later legs depend on it):
#
#   resolve     read group and artifact from the one `coordinates(` call of the core build
#               file, read the Maven metadata and the Hex package, and pick V = the numerically
#               highest X.Y.Z (no prerelease) present on BOTH registries. `--version` may name
#               another version but it must be on both. No version literal lives here.
#   generate    run script/verify_android_release_host.sh unchanged (published generator, real
#               HOME) to produce the host project
#   settings    the generated settings.gradle has no local repository source, no include of
#               the core project and no `project(`
#   coordinate  app/build.gradle has exactly one implementation line naming the artifact and
#               it equals implementation("<group>:<artifact>:V")
#   build       write a host-owned two-test JVM probe, run :app:testDebugUnitTest in a clean
#               environment, require tests >= 1 with no failures, errors or skips, and require
#               the probe class to load from <artifact>-V-runtime.jar under the run's own
#               GRADLE_USER_HOME caches
#   aar         the cached AAR's sha256 equals the digest Maven publishes next to it
#   control     the same project with the artifactId plus `-negctl` must fail for the right
#               reason: both `Could not find <group>:<artifact>-negctl:V` and
#               `Could not resolve all files for configuration`
#
# Exit codes: 0 every leg passed; 1 a leg failed; 2 usage error or a refused override. A
# missing tool is a FAIL (tool_unavailable), never a skip. A network failure is never a PASS.
#
# Output contract:
#   foreign-host: leg <name> PASS <V> <detail>
#   foreign-host: FAIL <leg> <reason>
#   foreign-host: result PASS|FAIL legs <passed legs, comma separated> version <V>
# Reasons (closed set):
#   any leg      tool_unavailable
#   resolve      coordinate_source_invalid, not_published (404 or no common version),
#                resolve_failed (network or parse error; separate from not_published)
#   generate     generate_failed
#   settings     settings_mismatch (also used if the clean HOME holds a local Maven copy of
#                the core artifact)
#   coordinate   coordinate_mismatch
#   build        build_failed, no_tests, probe_source_mismatch
#   aar          aar_checksum_mismatch
#   control      control_precondition_failed, control_passed (the control did not fail: the
#                proof is vacuous), control_inconclusive (network-looking failure),
#                control_wrong_reason
#
# With --evidence PATH a JSON file is written in every outcome: schema, target_version,
# head_sha, ran_on, tests, control_reason, script_blob, result, generator, reason. It holds
# only versions, commit ids, counts, a reason code and a blob id; nothing else.
#
# Selftest overrides (honored only with FOREIGN_HOST_SELFTEST=1; without it any of them exits 2):
#   FOREIGN_HOST_MAVEN_BASE, FOREIGN_HOST_HEX_API, FOREIGN_HOST_GENERATOR,
#   FOREIGN_HOST_CORE_BUILD_FILE (the build file the `coordinates(` call is read from),
#   FOREIGN_HOST_KEEP_WORK=1 (keep the work dir and print `foreign-host: work kept <path>`).

set -uo pipefail

MAVEN_DEFAULT_BASE="https://repo.maven.apache.org/maven2"
HEX_DEFAULT_API="https://hex.pm/api/packages/crosswake"
CURL_MAX_TIME=120
CURL_RETRY=2

SCRIPT_PATH="${BASH_SOURCE[0]}"
ROOT="$(cd "$(dirname "$SCRIPT_PATH")/.." && pwd)"
REAL_HOME="${HOME:-}"

usage() {
  echo "foreign-host: usage verify_android_foreign_host.sh [--version X.Y.Z] [--evidence PATH] [--head-sha SHA]"
  exit 2
}

REQUESTED_VERSION=""
EVIDENCE=""
HEAD_SHA=""
while [ "$#" -gt 0 ]; do
  case "$1" in
    --version) [ "$#" -ge 2 ] || usage; REQUESTED_VERSION="$2"; shift 2 ;;
    --evidence) [ "$#" -ge 2 ] || usage; EVIDENCE="$2"; shift 2 ;;
    --head-sha) [ "$#" -ge 2 ] || usage; HEAD_SHA="$2"; shift 2 ;;
    *) usage ;;
  esac
done
if [ -n "$REQUESTED_VERSION" ] && ! [[ "$REQUESTED_VERSION" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
  usage
fi
if [ -n "$HEAD_SHA" ] && ! [[ "$HEAD_SHA" =~ ^[0-9a-f]{40}$ ]]; then
  usage
fi

SELFTEST="${FOREIGN_HOST_SELFTEST:-}"
if [ "$SELFTEST" != "1" ]; then
  if [ -n "${FOREIGN_HOST_MAVEN_BASE:-}" ] || [ -n "${FOREIGN_HOST_HEX_API:-}" ] ||
    [ -n "${FOREIGN_HOST_GENERATOR:-}" ] || [ -n "${FOREIGN_HOST_CORE_BUILD_FILE:-}" ] ||
    [ -n "${FOREIGN_HOST_KEEP_WORK:-}" ]; then
    echo "foreign-host: override refused (set FOREIGN_HOST_SELFTEST=1 to use selftest overrides)"
    exit 2
  fi
else
  echo "foreign-host: selftest overrides active"
fi

MAVEN_BASE="${FOREIGN_HOST_MAVEN_BASE:-$MAVEN_DEFAULT_BASE}"
HEX_API="${FOREIGN_HOST_HEX_API:-$HEX_DEFAULT_API}"
GENERATOR="${FOREIGN_HOST_GENERATOR:-$ROOT/script/verify_android_release_host.sh}"
CORE_BUILD_FILE="${FOREIGN_HOST_CORE_BUILD_FILE:-$ROOT/packages/crosswake-shell-core-android/build.gradle.kts}"

# Never prompt for credentials; every registry is read anonymously.
export GIT_TERMINAL_PROMPT=0

FAILED=0
FAIL_LEG=""
FAIL_REASON=""
PASSED_LEGS=""
GROUP=""
ARTIFACT=""
V=""
PROJ=""
GUH=""
TESTS_COUNT=0
CONTROL_REASON="not_run"
BUILD_PASSED=0

WORK=""
cleanup() {
  [ -n "$WORK" ] || return 0
  if [ "$SELFTEST" = "1" ] && [ "${FOREIGN_HOST_KEEP_WORK:-}" = "1" ]; then
    echo "foreign-host: work kept $WORK"
    return 0
  fi
  rm -rf "$WORK"
}
trap cleanup EXIT

fail() { # leg reason
  echo "foreign-host: FAIL $1 $2"
  FAILED=1
  FAIL_LEG="$1"
  FAIL_REASON="$2"
}

pass() { # leg detail
  echo "foreign-host: leg $1 PASS ${V:-unknown} $2"
  if [ -z "$PASSED_LEGS" ]; then PASSED_LEGS="$1"; else PASSED_LEGS="$PASSED_LEGS,$1"; fi
}

need_tools() { # leg tool...
  local leg="$1" t
  shift
  for t in "$@"; do
    if ! command -v "$t" >/dev/null 2>&1; then
      fail "$leg" tool_unavailable
      return 1
    fi
  done
  return 0
}

sha256_of() { # file -> hex digest
  if command -v shasum >/dev/null 2>&1; then
    shasum -a 256 "$1" | cut -d' ' -f1
  else
    sha256sum "$1" | cut -d' ' -f1
  fi
}

# fetch <url> <dest>: 0 ok, 3 HTTP 404, 4 any other failure. Bounded and https-only,
# including after redirects. A 404 stays one fast answer: retry is not widened to it.
fetch() {
  local url="$1" dest="$2" code rc
  code=$(curl -sS -L --max-time "$CURL_MAX_TIME" --retry "$CURL_RETRY" --proto '=https' --proto-redir '=https' -o "$dest" -w '%{http_code}' "$url" 2>/dev/null)
  rc=$?
  [ "$rc" -eq 0 ] || return 4
  case "$code" in
    200) return 0 ;;
    404) return 3 ;;
    *) return 4 ;;
  esac
}

normalize_digest() { # file -> lowercase first token of first line
  tr -d '\r' <"$1" | head -n1 | cut -d' ' -f1 | tr 'A-F' 'a-f'
}

write_evidence() { # result
  [ -n "$EVIDENCE" ] || return 0
  local result="$1" ran_on blob head_sha
  ran_on="${GITHUB_SHA:-}"
  [ -n "$ran_on" ] || ran_on=$(git -C "$ROOT" rev-parse HEAD 2>/dev/null || echo unknown)
  head_sha="$HEAD_SHA"
  [ -n "$head_sha" ] || head_sha=$(git -C "$ROOT" rev-parse HEAD 2>/dev/null || echo unknown)
  blob=$(git -C "$ROOT" hash-object "$SCRIPT_PATH" 2>/dev/null || echo unknown)
  mkdir -p "$(dirname "$EVIDENCE")"
  jq -n \
    --arg target_version "${V:-unknown}" \
    --arg head_sha "$head_sha" \
    --arg ran_on "$ran_on" \
    --argjson tests "$TESTS_COUNT" \
    --arg control_reason "$CONTROL_REASON" \
    --arg script_blob "$blob" \
    --arg result "$result" \
    --arg reason "$FAIL_REASON" \
    '{schema: 1, target_version: $target_version, head_sha: $head_sha, ran_on: $ran_on,
      tests: $tests, control_reason: $control_reason, script_blob: $script_blob,
      result: $result, generator: "published", reason: $reason}' >"$EVIDENCE"
}

finish() {
  local result=PASS code=0
  if [ "$FAILED" -ne 0 ]; then
    result=FAIL
    code=1
  fi
  echo "foreign-host: result $result legs ${PASSED_LEGS:-none} version ${V:-unknown}"
  write_evidence "$result"
  exit "$code"
}

mk_work() {
  if [ -z "$WORK" ]; then
    WORK=$(mktemp -d "${TMPDIR:-${RUNNER_TEMP:-/tmp}}/crosswake-foreign-host.XXXXXX") || return 1
    WORK=$(cd -P "$WORK" && pwd -P) || return 1
  fi
}

# Sums the testsuite counters of every TEST-*.xml under a directory: "tests failures errors skipped files".
junit_totals() { # dir
  local dir="$1" files
  files=$(find "$dir" -maxdepth 1 -name 'TEST-*.xml' 2>/dev/null)
  if [ -z "$files" ]; then
    echo "0 0 0 0 0"
    return
  fi
  printf '%s\n' "$files" | while IFS= read -r f; do grep -h '<testsuite ' "$f" | head -n1; done | awk '
    function attr(line, name,   m) {
      if (match(line, " " name "=\"[0-9]+\"")) {
        m = substr(line, RSTART, RLENGTH)
        sub(/^[^"]*"/, "", m); sub(/"$/, "", m)
        return m + 0
      }
      return 0
    }
    { t += attr($0, "tests"); f += attr($0, "failures"); e += attr($0, "errors"); s += attr($0, "skipped"); n++ }
    END { printf "%d %d %d %d %d\n", t, f, e, s, n }'
}

# 0 when the named testcase has a failure or error child in any TEST-*.xml under the directory.
testcase_failed() { # dir name
  local dir="$1" name="$2" f
  for f in "$dir"/TEST-*.xml; do
    [ -f "$f" ] || continue
    if awk -v want="$name" '
      /<testcase / { cur = ($0 ~ ("name=\"" want "\"")) ? 1 : 0 }
      /<\/testcase>/ { cur = 0 }
      cur && (/<failure/ || /<error/) { found = 1 }
      END { exit(found ? 0 : 1) }' "$f"; then
      return 0
    fi
  done
  return 1
}

testcase_present() { # dir name
  local dir="$1" name="$2"
  grep -qs "<testcase name=\"$name\"" "$dir"/TEST-*.xml
}

clean_env() { # runs a command with the credential-free allowlist environment
  local args=(PATH="$PATH" HOME="$WORK/home" GRADLE_USER_HOME="$GUH" ANDROID_HOME="$SDK_ROOT"
    ANDROID_SDK_ROOT="$SDK_ROOT" TMPDIR="$WORK/tmp" LANG=C)
  [ -n "${JAVA_HOME:-}" ] && args+=(JAVA_HOME="$JAVA_HOME")
  env -i "${args[@]}" "$@"
}

leg_resolve() {
  need_tools resolve curl jq grep sed sort comm awk find head cut tr mktemp || return 1
  mk_work || { fail resolve tool_unavailable; return 1; }
  [ -f "$CORE_BUILD_FILE" ] || { fail resolve coordinate_source_invalid; return 1; }
  local hits line
  hits=$(grep -cF 'coordinates(' "$CORE_BUILD_FILE")
  if [ "$hits" != "1" ]; then
    fail resolve coordinate_source_invalid
    return 1
  fi
  line=$(grep -F 'coordinates(' "$CORE_BUILD_FILE")
  GROUP=$(printf '%s' "$line" | sed -nE 's/.*coordinates\("([^"]+)", *"([^"]+)".*/\1/p')
  ARTIFACT=$(printf '%s' "$line" | sed -nE 's/.*coordinates\("([^"]+)", *"([^"]+)".*/\2/p')
  if ! [[ "$GROUP" =~ ^[A-Za-z0-9._-]+$ ]] || ! [[ "$ARTIFACT" =~ ^[A-Za-z0-9._-]+$ ]]; then
    fail resolve coordinate_source_invalid
    return 1
  fi
  local group_path="${GROUP//./\/}" rc
  fetch "$MAVEN_BASE/$group_path/$ARTIFACT/maven-metadata.xml" "$WORK/maven-metadata.xml"; rc=$?
  if [ "$rc" -eq 3 ]; then fail resolve not_published; return 1; fi
  if [ "$rc" -ne 0 ]; then fail resolve resolve_failed; return 1; fi
  fetch "$HEX_API" "$WORK/hex-package.json"; rc=$?
  if [ "$rc" -eq 3 ]; then fail resolve not_published; return 1; fi
  if [ "$rc" -ne 0 ]; then fail resolve resolve_failed; return 1; fi
  local hex_raw
  if ! hex_raw=$(jq -r '.releases[]?.version // empty' "$WORK/hex-package.json" 2>/dev/null); then
    fail resolve resolve_failed
    return 1
  fi
  printf '%s\n' "$hex_raw" | grep -E '^[0-9]+\.[0-9]+\.[0-9]+$' | sort -u >"$WORK/hex-versions.txt"
  grep -Eo '<version>[0-9]+\.[0-9]+\.[0-9]+</version>' "$WORK/maven-metadata.xml" |
    sed -E 's#</?version>##g' | sort -u >"$WORK/maven-versions.txt"
  comm -12 "$WORK/maven-versions.txt" "$WORK/hex-versions.txt" >"$WORK/common-versions.txt"
  if [ -n "$REQUESTED_VERSION" ]; then
    if grep -qxF "$REQUESTED_VERSION" "$WORK/common-versions.txt"; then
      V="$REQUESTED_VERSION"
    else
      fail resolve not_published
      return 1
    fi
  else
    V=$(sort -t. -k1,1n -k2,2n -k3,3n "$WORK/common-versions.txt" | tail -n1)
    if [ -z "$V" ]; then
      fail resolve not_published
      return 1
    fi
  fi
  pass resolve "published $V, not head version"
}

leg_generate() {
  need_tools generate bash || return 1
  if ! bash "$GENERATOR" --version "$V" --host-root "$WORK/host" --target "$WORK/target" >"$WORK/generate.log" 2>&1; then
    tail -n 30 "$WORK/generate.log" >&2
    fail generate generate_failed
    return 1
  fi
  PROJ="$WORK/target/native/android/crosswake_shell"
  if [ ! -d "$PROJ" ]; then
    fail generate generate_failed
    return 1
  fi
  pass generate "generated by published crosswake $V"
}

leg_settings() {
  local settings="$PROJ/settings.gradle"
  if [ ! -f "$settings" ]; then
    fail settings settings_mismatch
    return 1
  fi
  if grep -qF 'mavenLocal()' "$settings" || grep -qF 'project(' "$settings" ||
    grep -E '^[[:space:]]*include' "$settings" | grep -qF "$ARTIFACT"; then
    fail settings settings_mismatch
    return 1
  fi
  pass settings "no local dependency source"
}

leg_coordinate() {
  local gradle="$PROJ/app/build.gradle" lines count line want
  if [ ! -f "$gradle" ]; then
    fail coordinate coordinate_mismatch
    return 1
  fi
  lines=$(grep -E '^[[:space:]]*implementation' "$gradle" | grep -F "$ARTIFACT")
  count=$(printf '%s' "$lines" | grep -c .)
  want="implementation(\"$GROUP:$ARTIFACT:$V\")"
  line=$(printf '%s' "$lines" | sed -E 's/^[[:space:]]+//; s/[[:space:]]+$//')
  if [ "$count" != "1" ] || [ "$line" != "$want" ]; then
    fail coordinate coordinate_mismatch
    return 1
  fi
  pass coordinate "$GROUP:$ARTIFACT:$V"
}

leg_build() {
  SDK_ROOT="${ANDROID_HOME:-${ANDROID_SDK_ROOT:-}}"
  if [ -z "$SDK_ROOT" ] || { [ -z "${JAVA_HOME:-}" ] && ! command -v java >/dev/null 2>&1; } ||
    { [ -n "${JAVA_HOME:-}" ] && [ ! -x "$JAVA_HOME/bin/java" ]; }; then
    fail build tool_unavailable
    return 1
  fi
  need_tools build env find cp mkdir ln awk || return 1
  mkdir -p "$WORK/home/.gradle" "$WORK/tmp" || { fail build tool_unavailable; return 1; }
  GUH=$(cd -P "$WORK/home/.gradle" && pwd -P)
  if [ -n "$REAL_HOME" ] && [ -d "$REAL_HOME/.crosswake/gradle" ]; then
    mkdir -p "$WORK/home/.crosswake"
    ln -s "$REAL_HOME/.crosswake/gradle" "$WORK/home/.crosswake/gradle"
  fi
  rm -rf "$GUH/caches/modules-2/files-2.1/$GROUP"

  local test_dir="$PROJ/app/src/test/java/dev/crosswake/shell"
  mkdir -p "$test_dir"
  cat >"$test_dir/ForeignHostResolveTest.kt" <<KOTLIN
package dev.crosswake.shell

import dev.crosswake.shell.core.CrosswakeShellConfig
import org.junit.Assert.assertTrue
import org.junit.Test

class ForeignHostResolveTest {
    @Test
    fun probeBehavesAsPublished() {
        assertTrue(CrosswakeShellConfig().registeredCapabilities.isEmpty())
    }

    @Test
    fun probeLoadsFromPublishedArtifactCache() {
        val location = CrosswakeShellConfig::class.java.protectionDomain.codeSource.location
        val path = java.io.File(location.toURI()).path
        assertTrue(path, path.startsWith("$GUH/caches/"))
        assertTrue(path, path.endsWith("/$ARTIFACT-$V-runtime.jar"))
    }
}
KOTLIN

  local rc
  (cd "$PROJ" && clean_env ./gradlew --no-daemon --refresh-dependencies :app:testDebugUnitTest) >"$WORK/build.log" 2>&1
  rc=$?
  local results="$PROJ/app/build/test-results/testDebugUnitTest"
  if [ "$rc" -ne 0 ]; then
    if testcase_failed "$results" probeLoadsFromPublishedArtifactCache; then
      fail build probe_source_mismatch
    else
      tail -n 40 "$WORK/build.log" >&2
      fail build build_failed
    fi
    return 1
  fi
  local totals tests failures errors skipped files
  totals=$(junit_totals "$results")
  read -r tests failures errors skipped files <<<"$totals"
  if [ "$files" -lt 1 ] || [ "$tests" -lt 1 ] || [ "$((failures + errors + skipped))" -ne 0 ] ||
    ! testcase_present "$results" probeBehavesAsPublished ||
    ! testcase_present "$results" probeLoadsFromPublishedArtifactCache; then
    fail build no_tests
    return 1
  fi
  TESTS_COUNT="$tests"
  if [ -e "$WORK/home/.m2/repository/io/github/sztheory" ]; then
    fail build settings_mismatch
    return 1
  fi
  BUILD_PASSED=1
  pass build "tests $tests failures 0 skipped 0"
}

leg_aar() {
  local group_path="${GROUP//./\/}" dir aars count aar want got rc
  dir="$GUH/caches/modules-2/files-2.1/$GROUP/$ARTIFACT/$V"
  aars=$(find "$dir" -name "$ARTIFACT-$V.aar" 2>/dev/null)
  count=$(printf '%s' "$aars" | grep -c .)
  if [ "$count" != "1" ]; then
    fail aar aar_checksum_mismatch
    return 1
  fi
  aar="$aars"
  fetch "$MAVEN_BASE/$group_path/$ARTIFACT/$V/$ARTIFACT-$V.aar.sha256" "$WORK/aar.sha256"; rc=$?
  if [ "$rc" -ne 0 ]; then
    fail aar aar_checksum_mismatch
    return 1
  fi
  want=$(normalize_digest "$WORK/aar.sha256")
  got=$(sha256_of "$aar")
  if [ -z "$want" ] || [ "$want" != "$got" ]; then
    fail aar aar_checksum_mismatch
    return 1
  fi
  pass aar "sha256 $got"
}

leg_control() {
  local group_path="${GROUP//./\/}" bad="$ARTIFACT-negctl" rc ctl="$WORK/control"
  if [ "$BUILD_PASSED" -ne 1 ]; then
    fail control control_precondition_failed
    return 1
  fi
  fetch "$MAVEN_BASE/$group_path/$bad/$V/$bad-$V.pom" "$WORK/negctl.pom"; rc=$?
  if [ "$rc" -ne 3 ]; then
    fail control control_precondition_failed
    return 1
  fi
  rm -rf "$ctl"
  cp -R "$PROJ" "$ctl" || { fail control control_precondition_failed; return 1; }
  rm -rf "$ctl/app/build" "$ctl/build" "$ctl/.gradle"
  sed -i.bak "s#$GROUP:$ARTIFACT:$V#$GROUP:$bad:$V#" "$ctl/app/build.gradle"
  if [ "$(diff "$ctl/app/build.gradle.bak" "$ctl/app/build.gradle" | grep -c '^>')" != "1" ]; then
    fail control control_precondition_failed
    return 1
  fi
  (cd "$ctl" && clean_env ./gradlew --no-daemon :app:testDebugUnitTest --dry-run) >"$WORK/control-dry.log" 2>&1
  if [ "$?" -ne 0 ]; then
    fail control control_precondition_failed
    return 1
  fi
  (cd "$ctl" && clean_env ./gradlew --no-daemon :app:testDebugUnitTest) >"$WORK/control.log" 2>&1
  rc=$?
  if [ "$rc" -eq 0 ]; then
    CONTROL_REASON="control_passed"
    fail control control_passed
    return 1
  fi
  if grep -qE 'Could not GET|UnknownHost|Read timed out|Connection' "$WORK/control.log"; then
    CONTROL_REASON="control_inconclusive"
    fail control control_inconclusive
    return 1
  fi
  if grep -qF "Could not find $GROUP:$bad:$V" "$WORK/control.log" &&
    grep -qF 'Could not resolve all files for configuration' "$WORK/control.log"; then
    CONTROL_REASON="could_not_find"
    grep -F "Could not find $GROUP:$bad:$V" "$WORK/control.log" | head -n1 | sed 's/^/foreign-host: control matched /'
    grep -F 'Could not resolve all files for configuration' "$WORK/control.log" | head -n1 | sed 's/^/foreign-host: control matched /'
    pass control "control_reason=could_not_find"
    return 0
  fi
  CONTROL_REASON="control_wrong_reason"
  tail -n 30 "$WORK/control.log" >&2
  fail control control_wrong_reason
  return 1
}

leg_resolve || finish
leg_generate || finish
leg_settings || finish
leg_coordinate || finish
leg_build || finish
leg_aar || finish
leg_control || finish
finish
